$js=@'
const fs=require("fs"),path=require("path");
const U=process.env.USERPROFILE;
function desc(p){try{const c=fs.readFileSync(p,"utf8");const m=c.match(/^---\r?\n([\s\S]*?)\r?\n---/);if(!m)return "(no frontmatter)";const d=m[1].match(/^description:\s*(.+)$/m);return d?d[1].replace(/\s+/g," ").slice(0,180):"(no description)";}catch(e){return "(no SKILL.md)";}}
console.log("=== LOADED SKILLS (frontmatter description) ===");
const sd=path.join(U,".dsh/skills");
for(const n of fs.readdirSync(sd).sort()){const p=path.join(sd,n,"SKILL.md");if(fs.existsSync(p))console.log(n+" :: "+desc(p));}
console.log("\n=== REPO-ONLY SKILLS (not linked) ===");
const linked=new Set(fs.readdirSync(sd));
for(const n of fs.readdirSync("D:/repository/skills").sort()){if(linked.has(n))continue;const p=path.join("D:/repository/skills",n,"SKILL.md");if(fs.existsSync(p))console.log(n+" :: "+desc(p));}
console.log("\n=== PLUGINS (package.json description / name) ===");
for(const base of [path.join(U,".dsh"),"D:/repository/skills/dsh"]){for(const n of fs.readdirSync(base).sort()){const pj=path.join(base,n,"package.json");if(!fs.existsSync(pj))continue;try{const j=JSON.parse(fs.readFileSync(pj,"utf8"));console.log(n+" :: "+(j.description||j.name||"").replace(/\s+/g," ").slice(0,140));}catch(e){}}}
'@; $js|Out-File "$env:TEMP\ovl.js" -Encoding utf8; node "$env:TEMP\ovl.js"; Remove-Item "$env:TEMP\ovl.js" -Force -EA SilentlyContinue

